<script setup lang="ts">
import {computed,ref,useId,watch} from 'vue'
import {ArrowRight,BookOpen,Check,ChevronDown,Cloud,Download,FileSearch,Layers3,Monitor,Settings,ShieldCheck,Sparkles} from 'lucide-vue-next'
import ResultText from './ResultText.vue'
import {dashboardHighlights} from '../lib/dashboardReadability'
import {analysisDashboardSections,analysisDetailIssue,dashboardSource,isStale,latestReport,readReports,reportQualityIssue,resultDashboardSections,schoolConnectionContext,stageIssue,type PreparationStage,type Report} from '../lib/preparationReports'
import type {CounselingCase,Session} from '../lib/types'
import analysisCriteria from '../data/analysis-criteria.json'

const props=defineProps<{caseValue:CounselingCase;session:Session;busy:boolean;currentSourceHash?:string;initialStage?:PreparationStage;generationError?:string;progress?:string}>()
const emit=defineEmits<{generate:[stage:'admissions'|'inquiry',targetId:string];download:[kind:'analysis'|'admissions'|'inquiry',targetId?:string];analyze:[];settings:[]}>()
const id=useId(),active=ref<PreparationStage>(props.initialStage||'analysis'),selectedTargetId=ref('')
watch(()=>props.initialStage,value=>{if(value)active.value=value})
const phases=[
 {id:'analysis' as const,title:'학생부 분석',short:'학생부 분석',description:'기록의 사실과 해석을 구분하고, 다음 준비에 사용할 강점과 보완점을 확인합니다.',icon:FileSearch},
 {id:'admissions' as const,title:'대학·학과별 학종 준비',short:'대학·학과 준비',description:'대학의 공식 평가와 전공의 학습 기반을 학생의 현재 학습과 연결합니다.',icon:Layers3},
 {id:'inquiry' as const,title:'질문 중심 학습',short:'질문 중심 학습',description:'준비할 이유를 중심 질문으로 좁히고, 개념 학습과 실제 학교 과제로 이어갑니다.',icon:BookOpen},
]
const targets=computed(()=>{
 const rows=props.session.profile?.admission_targets?.length?props.session.profile.admission_targets:props.session.student_admission_targets||[]
 return rows.filter(row=>row.university.trim()||row.major.trim())
})
watch(()=>props.session.id,()=>{active.value='analysis';selectedTargetId.value=''})
watch(targets,rows=>{if(!rows.some(row=>row.id===selectedTargetId.value))selectedTargetId.value=rows[0]?.id||''},{immediate:true})
const target=computed(()=>targets.value.find(row=>row.id===selectedTargetId.value))
const reports=computed(()=>readReports((props.session as Session&{preparation_reports?:unknown}).preparation_reports))
const admissions=computed(()=>latestReport(reports.value,'admissions',selectedTargetId.value))
const report=computed(()=>active.value==='analysis'?undefined:latestReport(reports.value,active.value,selectedTargetId.value))
const phase=computed(()=>phases.find(item=>item.id===active.value)!)
const schoolStudent=computed(()=>props.session.student_snapshot||props.caseValue.student)
const sections=computed(()=>active.value==='analysis'?analysisDashboardSections(props.session):resultDashboardSections(active.value,report.value))
const highlights=computed(()=>dashboardHighlights(active.value,props.session,sections.value))
const requirement=computed(()=>stageIssue(props.session,active.value,target.value,admissions.value,props.currentSourceHash))
const quality=computed(()=>active.value==='analysis'?'':reportQualityIssue(report.value))
const analysisDetail=computed(()=>analysisDetailIssue(props.session))
const stale=computed(()=>!!report.value&&isStale(report.value,props.currentSourceHash))
const downloadIssue=computed(()=>active.value==='analysis'?requirement.value:props.session.imported_unverified?'가져온 결과는 현재 자료를 확인한 뒤 다시 생성해 주세요.':quality.value||(!props.currentSourceHash?'최신 입력을 확인한 뒤 PDF로 저장할 수 있습니다.':stale.value?'입력 내용이 달라졌습니다. 전략을 다시 생성한 뒤 저장해 주세요.':''))
const notes=computed(()=>[
 {label:'교사 관찰',text:props.session.profile?.teacher_observations||''},
 {label:'상담 내용',text:[props.session.consultation?.student_response,props.session.consultation?.summary].filter(Boolean).join('\n')},
 {label:'교사 의견',text:props.session.teacher_opinion||''},
].filter(note=>note.text.trim()))
const stateText=computed(()=>{
 if(active.value==='analysis')return !props.session.analysis?'분석 전':requirement.value?'원본 연결 확인 필요':analysisDetail.value?'부분 분석 · 상세 근거 추가 필요':'상세 분석 · 다섯 영역의 근거와 준비 방향'
 if(!report.value)return '전략 생성 전'
 if(quality.value)return '내용 보완 필요'
 if(!props.currentSourceHash)return '최신 여부 확인 필요'
 return stale.value?'입력 변경 · 다시 생성':'생성된 초안 · 검토 필요'
})
function targetState(targetId:string){const result=latestReport(reports.value,active.value==='inquiry'?'inquiry':'admissions',targetId);return !result?'생성 전':reportQualityIssue(result)?'내용 보완 필요':!props.currentSourceHash?'최신 여부 확인 필요':isStale(result,props.currentSourceHash)?'입력 변경':'초안 있음'}
function sourceRows(refs:string[]){return [...new Set(refs)].map(ref=>dashboardSource(ref,props.session,report.value,admissions.value))}
function reportDate(value:Report|undefined){return value&&/^\d{4}-\d{2}-\d{2}/.test(value.created_at)?value.created_at.slice(0,10):''}
function generate(){if(active.value!=='analysis'&&target.value&&!requirement.value)emit('generate',active.value,target.value.id)}
function download(){if(!downloadIssue.value)emit('download',active.value,active.value==='analysis'?undefined:selectedTargetId.value)}
function navigateTabs(event:KeyboardEvent){
 const current=phases.findIndex(item=>item.id===active.value)
 const index=event.key==='ArrowRight'?(current+1)%phases.length:event.key==='ArrowLeft'?(current+phases.length-1)%phases.length:event.key==='Home'?0:event.key==='End'?phases.length-1:-1
 if(index<0)return;event.preventDefault();active.value=phases[index]!.id;document.getElementById(id+'-tab-'+active.value)?.focus()
}
</script>

<template>
 <section class="preparation-dashboard" aria-label="학생부에서 질문 학습으로 이어지는 준비 대시보드">
  <header class="dashboard-heading"><div><span class="dashboard-eyebrow">학종 준비 · {{session.date}}</span><h2>분석에서 다음 배움까지</h2><p>학생부의 근거를 확인하고 대학·학과 준비, 질문 중심 학습으로 이어갑니다.</p></div><span class="storage-note"><ShieldCheck :size="16"/>결과와 근거는 이 PC에서 확인</span></header>
  <div class="stage-tabs" role="tablist" aria-label="학종 준비 단계" @keydown="navigateTabs">
   <button v-for="(item,index) in phases" :id="id+'-tab-'+item.id" :key="item.id" type="button" role="tab" :aria-selected="active===item.id" :aria-controls="id+'-panel'" :tabindex="active===item.id?0:-1" :class="{selected:active===item.id}" @click="active=item.id"><span class="stage-number">0{{index+1}}</span><span class="stage-name">{{item.short}}<small>{{item.id==='analysis'?'로컬 AI':'외부 AI · 전송 전 검사'}}</small></span><ArrowRight v-if="index<2" :size="17" class="stage-arrow"/></button>
  </div>

  <section :id="id+'-panel'" role="tabpanel" :aria-labelledby="id+'-tab-'+active" tabindex="0" class="stage-panel">
   <div class="phase-heading"><div><span class="processing-chip"><Monitor v-if="active==='analysis'" :size="15"/><Cloud v-else :size="15"/>{{active==='analysis'?'이 PC에서 학생부 분석':'검사한 학습 요약으로 전략 생성'}}</span><h3>{{phase.title}}</h3><p>{{phase.description}}</p></div><button type="button" class="settings-button" :disabled="busy" @click="emit('settings')"><Settings :size="16"/>AI 연결 설정</button></div>

   <section v-if="active!=='analysis'" class="targets-panel" aria-label="준비할 대학·학과 선택">
    <div class="target-heading"><h4>대학·학과별로 준비하기</h4><small>학생부종합전형</small></div>
    <div v-if="targets.length" class="target-grid"><button v-for="row in targets" :key="row.id" type="button" class="target-card" :aria-pressed="selectedTargetId===row.id" @click="selectedTargetId=row.id"><span class="target-university">{{row.university||'대학 입력 필요'}}<Check v-if="selectedTargetId===row.id" :size="17"/></span><strong>{{row.major||'학과 입력 필요'}}</strong><span>{{[row.admission_year?row.admission_year+'학년도':'대입 학년도 미입력',row.admission_name].filter(Boolean).join(' · ')}}</span><small>{{targetState(row.id)}}</small></button></div>
    <p v-else class="empty-target">학생 기본자료에서 희망 대학·학과를 입력하면 목표별로 전략을 이어갈 수 있습니다.</p>
   </section>

   <div class="source-chain" aria-label="현재 결과의 근거 연결"><span><FileSearch :size="15"/>{{active==='analysis'?'학생부 원문':'학생부 원문·분석'}}</span><ArrowRight :size="15"/><span :class="{current:active!=='inquiry'}">{{active==='analysis'?'로컬 학생부 분석':'대학·학과 공식 자료'}}</span><template v-if="active==='inquiry'"><ArrowRight :size="15"/><span class="current">학종 준비 → 탐구 질문</span></template><small>{{active==='analysis'?'사실과 해석을 근거별로 확인':'공개 기준과 학생의 학습 판단을 구분하여 확인'}}</small></div>
   <div class="result-toolbar"><div><span class="result-state" :class="{attention:stale||!!quality&&!!report}">{{stateText}}</span><small v-if="reportDate(report)">생성일 {{reportDate(report)}}</small></div><div class="result-actions"><button v-if="active==='analysis'" type="button" class="primary" :disabled="busy" @click="emit('analyze')"><FileSearch :size="17"/>{{session.record?'학생부 분석하기':'학생부 가져오기·분석'}}</button><button v-else type="button" class="primary" :disabled="busy||!!requirement" @click="generate"><Sparkles :size="17"/>{{report?'전략 다시 생성':'전략 생성'}}</button><button type="button" class="secondary" :disabled="busy||!!downloadIssue" @click="download"><Download :size="17"/>이 결과 PDF 저장</button></div></div>
   <p v-if="busy" class="result-notice" role="status" aria-live="polite">{{progress||'전략 생성을 준비하고 있습니다.'}}</p>
   <p v-if="generationError" class="result-notice" role="alert">{{generationError}}</p>
   <p v-if="requirement" class="result-notice" role="status">{{requirement}}</p><p v-else-if="active==='analysis'&&analysisDetail" class="result-notice" role="status">{{analysisDetail}}</p><p v-else-if="downloadIssue&&report" class="result-notice" role="status">{{downloadIssue}}</p>
   <section v-if="highlights.length" class="result-brief" aria-label="결과 핵심 요약">
    <header><div><span class="dashboard-eyebrow">한눈에 보는 결과</span><h4>{{active==='analysis'?'분석에서 먼저 볼 내용':active==='admissions'?'먼저 살펴볼 준비':'탐구를 시작할 질문'}}</h4></div><p>{{active==='analysis'?'항목 수는 저장된 판단의 수이며 역량 점수가 아닙니다.':'저장된 제안 순서입니다. 실행 조건은 상세 내용에서 확인하세요.'}}</p></header>
    <div class="brief-grid"><a v-for="(item,index) in highlights" :key="index" class="brief-card" :class="'brief-'+index" :href="'#'+id+'-'+active+'-'+item.sectionId"><span class="brief-label">{{item.label}}</span><strong>{{item.title}}</strong><p>{{item.text}}</p><span class="brief-link">전체 내용과 조건 보기 <ArrowRight :size="14"/></span></a></div>
   </section>
   <article v-if="report?.summary" class="result-summary"><span class="dashboard-eyebrow">이번 목표의 준비 방향</span><h4>{{report.title}}</h4><ResultText :text="report.summary"/></article>

   <nav class="section-index" aria-label="상세 내용 목차"><a v-for="(section,index) in sections" :key="section.id" :href="'#'+id+'-'+active+'-'+section.id"><span>0{{index+1}}</span>{{section.title}}<small>{{section.items.length?section.items.length+'개 항목':'자료 확인'}}</small></a></nav>
   <div class="report-sections">
    <section v-for="(section,index) in sections" :id="id+'-'+active+'-'+section.id" :key="section.id" class="report-section" :class="{'record-section':active==='analysis'&&index===0}">
     <header><span class="section-number">0{{index+1}}</span><div><h4>{{section.title}}</h4><details v-if="section.overview" class="section-overview"><summary>이 영역의 전체 설명</summary><ResultText :text="section.overview"/></details></div></header>
     <p v-if="!section.items.length" class="section-empty">{{section.empty}}<span>{{active==='analysis'?'확인된 분석 근거가 있으면 이 영역에 표시합니다.':'전략을 생성하면 이 영역의 구체적인 설명과 준비 방법을 확인할 수 있습니다.'}}</span></p>
     <div v-else class="detail-items">
      <article v-for="(item,itemIndex) in section.items" :key="itemIndex" class="detail-item">
       <h5><span class="item-number">{{String(itemIndex+1).padStart(2,'0')}}</span>{{item.title}}</h5>
       <div class="item-explanation">
        <div class="item-content"><strong class="content-label">{{active==='analysis'?'확인한 내용':'준비 내용'}}</strong><ResultText :text="item.detail"/></div>
        <div v-if="item.reason" class="item-reason"><strong>{{active==='analysis'?'해석·지원 방향':'선택 이유'}}</strong><ResultText :text="item.reason"/></div>
       </div>
       <div v-if="item.steps.length" class="learning-method"><strong>실행 순서 · 준비할 결과물과 점검</strong><ol><li v-for="(step,stepIndex) in item.steps" :key="stepIndex"><ResultText :text="step"/></li></ol></div>
       <details v-if="item.evidence_refs.length" class="item-sources"><summary><BookOpen :size="15"/>판단에 사용한 근거 <ChevronDown :size="15"/></summary><div v-for="(source,sourceIndex) in sourceRows(item.evidence_refs)" :key="sourceIndex" class="source-detail"><strong>{{source.label}}</strong><a v-if="source.url" :href="source.url" target="_blank" rel="noopener noreferrer">공식 자료 열기 <ArrowRight :size="14"/></a><p>{{source.text||'제공된 자료에 내용이 없습니다.'}}</p></div></details>
      </article>
     </div>
    </section>
   </div>

   <section v-if="report?.school_connections?.length" class="school-connections"><h4>이 학교의 과제·활동과 대조</h4><p>원문 계획과 실제 운영을 확인하고, 과제에서 정한 절차·분량·허용 조건을 적용합니다.</p><article v-for="(connection,index) in report.school_connections" :key="index"><h5>{{[connection.subject,connection.task].filter(Boolean).join(' · ')}}</h5><p class="school-scope"><strong>원문 적용 범위: {{schoolConnectionContext(connection,schoolStudent).scope}}</strong><br>{{schoolConnectionContext(connection,schoolStudent).notice}}</p><small v-if="connection.status">자료 상태: {{connection.status}}</small><ResultText :text="connection.reason"/><ul><li v-for="(condition,conditionIndex) in connection.conditions" :key="conditionIndex">{{condition}}</li></ul><p v-if="connection.learning_topics?.length" class="school-topics">연결할 학습 내용: {{connection.learning_topics.join(' · ')}}</p><div v-if="connection.steps?.length" class="school-steps"><strong>원래 수행 절차</strong><ol><li v-for="(step,stepIndex) in connection.steps" :key="stepIndex">{{step}}</li></ol></div><small v-if="connection.source">근거: {{connection.source}}</small></article></section>
   <details v-if="active==='analysis'" class="analysis-criteria" aria-label="학생부 평가 기준">
    <summary>{{analysisCriteria.title}}<span>평가 관점·자료 범위 보기</span></summary><p>{{analysisCriteria.scope}}</p>
    <div class="criteria-grid"><article v-for="row in analysisCriteria.competencies" :key="row.label"><h5>{{row.label}}</h5><strong>{{row.criteria}}</strong><p>{{row.evidence}}</p></article></div>
    <details><summary>학교생활기록부 영역별 평가 관점</summary><dl><template v-for="row in analysisCriteria.record_areas" :key="row.label"><dt>{{row.label}}</dt><dd>{{row.criteria}}</dd></template></dl><p>{{analysisCriteria.interpretation}}</p><small v-for="source in analysisCriteria.sources" :key="source">{{source}}</small></details>
   </details>

   <details class="optional-context"><summary>교사 관찰·상담·의견 <span>선택 입력{{notes.length?' · 참고 내용 있음':''}}</span><ChevronDown :size="16"/></summary><p>어느 단계에서든 기존 입력 화면에 내용을 더할 수 있습니다. 입력을 바꾼 뒤 관련 전략을 다시 생성하면 반영됩니다.</p><article v-for="note in notes" :key="note.label"><h4>{{note.label}}</h4><p>{{note.text}}</p></article><p v-if="!notes.length">현재 추가로 입력한 내용이 없습니다. 학생부와 확인된 자료로 준비를 시작할 수 있습니다.</p></details>
   <p class="dashboard-footnote"><ShieldCheck :size="15"/>{{active==='analysis'?'학생부 사실과 교육적 해석을 구분하여 검토합니다.':'학생부 원본·상세 분석 전체를 보내지 않고, 전송 검사를 통과한 학습 요약을 사용합니다.'}}</p>
  </section>
 </section>
</template>

<style scoped>
.preparation-dashboard{min-width:0;color:#18283d;--dashboard-blue:#2c5297;--dashboard-border:#dce4ee;--dashboard-muted:#56667b}.dashboard-heading,.phase-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:24px}.dashboard-heading{padding:8px 0 25px}.dashboard-eyebrow{font-size:12px;font-weight:700;color:var(--dashboard-blue);letter-spacing:.02em}.dashboard-heading h2{font-size:28px;line-height:1.4;margin:8px 0}.dashboard-heading p,.phase-heading p{color:var(--dashboard-muted);font-size:14px;line-height:1.8;margin:7px 0}.storage-note{display:flex;align-items:center;gap:7px;font-size:12px;color:var(--dashboard-muted);white-space:nowrap;padding-top:8px}.stage-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid var(--dashboard-border);border-radius:12px;overflow:hidden;background:#f7f9fc}.stage-tabs button{display:flex;align-items:center;gap:12px;min-width:0;padding:21px 20px;text-align:left;border:0;border-right:1px solid var(--dashboard-border);border-radius:0;background:transparent;color:var(--dashboard-muted)}.stage-tabs button:last-child{border-right:0}.stage-tabs button.selected{background:var(--dashboard-blue);color:white}.stage-number{font-size:13px;font-weight:700;opacity:.8}.stage-name{font-size:16px;font-weight:700;line-height:1.6;flex:1}.stage-name small{display:block;font-size:11px;font-weight:400;opacity:.86}.stage-arrow{flex:none}.stage-panel{padding-top:28px;outline-offset:5px}.phase-heading h3{font-size:24px;line-height:1.5;margin:12px 0 5px}.processing-chip{display:inline-flex;align-items:center;gap:6px;background:#edf3fb;padding:6px 9px;border-radius:5px;color:#31578d;font-size:12px}.settings-button{display:flex;align-items:center;gap:7px;flex:none;font-size:12px;border:1px solid var(--dashboard-border);background:white;border-radius:6px;padding:9px 11px}.targets-panel{margin:22px 0;padding:20px;background:#f8fafc;border:1px solid var(--dashboard-border);border-radius:10px}.target-heading{display:f